"""
OAuth Configuration and Setup Guide

This module provides guidance for setting up OAuth authentication.

SETUP STEPS:
============

1. Install dependencies:
   pip install authlib flask

2. Choose OAuth Providers:
   - Google OAuth (recommended for quick setup)
   - GitHub OAuth (for developer-focused apps)

3. Get OAuth Credentials:

   For Google:
   - Go to https://console.cloud.google.com/
   - Create a new project
   - Enable Google+ API
   - Create OAuth 2.0 credentials (Web application)
   - Add http://localhost:5000/auth/callback/google as authorized redirect URI
   - Copy Client ID and Secret

   For GitHub:
   - Go to https://github.com/settings/developers
   - Create a new OAuth App
   - Set Authorization callback URL to http://localhost:5000/auth/callback/github
   - Copy Client ID and Secret

4. Set Environment Variables:
   export OAUTH_GOOGLE_CLIENT_ID=your_google_client_id
   export OAUTH_GOOGLE_CLIENT_SECRET=your_google_client_secret
   export OAUTH_GITHUB_CLIENT_ID=your_github_client_id
   export OAUTH_GITHUB_CLIENT_SECRET=your_github_client_secret

5. Update Flask App:
   from web.auth.login import init_oauth

   app = Flask(__name__)
   app.secret_key = 'your-secret-key-here'
   init_oauth(app)

6. Add Routes to your Flask app:
   @app.route('/auth/login/<provider>')
   def login(provider):
       from web.auth.login import login_oauth
       return login_oauth(provider)

   @app.route('/auth/callback/<provider>')
   def oauth_callback(provider):
       from web.auth.login import oauth_callback
       return oauth_callback(provider)

   @app.route('/logout')
   def logout():
       from web.auth.login import logout
       return logout()

7. Protect Routes with Login:
   from functools import wraps
   from web.auth.login import is_authenticated

   def login_required(f):
       @wraps(f)
       def decorated_function(*args, **kwargs):
           if not is_authenticated():
               return redirect(url_for('login'))
           return f(*args, **kwargs)
       return decorated_function

   @app.route('/dashboard')
   @login_required
   def dashboard():
       return render_template('dashboard.html')
"""

# Configuration constants
OAUTH_PROVIDERS = {
    'google': {
        'name': 'Google',
        'icon': 'google',
        'authorize_url': 'https://accounts.google.com/o/oauth2/v2/auth',
        'token_url': 'https://oauth2.googleapis.com/token',
        'scopes': ['openid', 'email', 'profile']
    },
    'github': {
        'name': 'GitHub',
        'icon': 'github',
        'authorize_url': 'https://github.com/login/oauth/authorize',
        'token_url': 'https://github.com/login/oauth/access_token',
        'scopes': ['user:email']
    }
}

# Default session configuration
SESSION_CONFIG = {
    'SESSION_COOKIE_SECURE': True,  # Only send over HTTPS in production
    'SESSION_COOKIE_HTTPONLY': True,  # Prevent JavaScript access
    'SESSION_COOKIE_SAMESITE': 'Lax',  # CSRF protection
    'PERMANENT_SESSION_LIFETIME': 7 * 24 * 60 * 60  # 7 days
}

"""
Example Flask application showing how to use OAuth authentication.

This is a template for integrating the new OAuth login system.
Copy and adapt this to your main Flask app.
"""

from flask import Flask, render_template, redirect, url_for, session
from functools import wraps
import os

# Import the OAuth authentication module
from login import init_oauth, login_oauth, oauth_callback, logout, is_authenticated, get_current_user

# Initialize Flask app
app = Flask(__name__)
app.secret_key = os.getenv('SECRET_KEY', 'dev-secret-key-change-in-production')

# Configure session security
app.config.update({
    'SESSION_COOKIE_SECURE': os.getenv('FLASK_ENV') == 'production',
    'SESSION_COOKIE_HTTPONLY': True,
    'SESSION_COOKIE_SAMESITE': 'Lax',
    'PERMANENT_SESSION_LIFETIME': 7 * 24 * 60 * 60
})

# Initialize OAuth
init_oauth(app)


# ============================================================================
# MIDDLEWARE & DECORATORS
# ============================================================================

def login_required(f):
    """Decorator to require login for a route."""
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if not is_authenticated():
            return redirect(url_for('login_page'))
        return f(*args, **kwargs)
    return decorated_function


# ============================================================================
# AUTHENTICATION ROUTES
# ============================================================================

@app.route('/')
def index():
    """Home page - show login options if not authenticated."""
    if is_authenticated():
        return redirect(url_for('dashboard'))
    return render_template('index.html')


@app.route('/login')
def login_page():
    """Login page with OAuth provider options."""
    return render_template('login.html')


@app.route('/auth/login/<provider>')
def login(provider):
    """Initiate OAuth login flow."""
    try:
        return login_oauth(provider)
    except Exception as e:
        return {'error': f'Login failed: {str(e)}'}, 500


@app.route('/auth/callback/<provider>')
def callback(provider):
    """Handle OAuth provider callback."""
    try:
        return oauth_callback(provider)
    except Exception as e:
        return {'error': f'Authentication failed: {str(e)}'}, 500


@app.route('/logout')
def logout_route():
    """Logout the user."""
    return logout()


# ============================================================================
# PROTECTED ROUTES
# ============================================================================

@app.route('/dashboard')
@login_required
def dashboard():
    """Dashboard - only accessible to authenticated users."""
    user = get_current_user()
    return render_template('dashboard.html', user=user)


@app.route('/profile')
@login_required
def profile():
    """User profile page."""
    user = get_current_user()
    return render_template('profile.html', user=user)


@app.route('/settings')
@login_required
def settings():
    """User settings page."""
    user = get_current_user()
    return render_template('settings.html', user=user)


# ============================================================================
# ERROR HANDLERS
# ============================================================================

@app.errorhandler(404)
def not_found(error):
    """Handle 404 errors."""
    return render_template('404.html'), 404


@app.errorhandler(500)
def server_error(error):
    """Handle 500 errors."""
    return render_template('500.html'), 500


# ============================================================================
# TEMPLATE HELPERS
# ============================================================================

@app.context_processor
def inject_user():
    """Make user info available in all templates."""
    return {
        'current_user': get_current_user(),
        'is_authenticated': is_authenticated()
    }


# ============================================================================
# APPLICATION ENTRY POINT
# ============================================================================

if __name__ == '__main__':
    # Development settings
    debug = os.getenv('FLASK_ENV') == 'development'
    port = int(os.getenv('PORT', 5000))

    print(f"Starting Flask app on port {port}...")
    print(f"Debug mode: {debug}")
    print(f"Make sure to set OAuth environment variables!")

    app.run(
        host='0.0.0.0',
        port=port,
        debug=debug
    )

